package com.raktasetu.controller;
import com.raktasetu.dto.Forms.*;
import com.raktasetu.model.*;
import com.raktasetu.repository.*;
import jakarta.validation.Valid;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;
@RestController @RequestMapping("/api")
public class ApiController {
 private final UserRepository users; private final RequestRepository requests; private final PasswordEncoder passwords;
 public ApiController(UserRepository users,RequestRepository requests,PasswordEncoder passwords){this.users=users;this.requests=requests;this.passwords=passwords;}
 private User current(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
 private String normGroup(String blood){String b=blood==null?"":blood.trim().toUpperCase();if(!Set.of("A+","A-","B+","B-","AB+","AB-","O+","O-").contains(b))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose valid blood group");return b;}
 private String safe(String str){return str==null?"":str.trim();}
 @PostMapping("/auth/register") public Map<String,String> register(@Valid @RequestBody Registration f){
   String role=safe(f.role()).toUpperCase();if(!Set.of("DONOR","REQUESTER").contains(role))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose Donor or Requester");
   if(users.existsByEmailIgnoreCase(safe(f.email())))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");
   User u=new User();u.name=safe(f.name());u.email=safe(f.email()).toLowerCase();u.password=passwords.encode(f.password());u.role=role;u.mobile=safe(f.mobile());u.city=safe(f.city());u.state=safe(f.state());u.bloodGroup=role.equals("DONOR")?normGroup(f.bloodGroup()):null;users.save(u);return Map.of("message","Account created. Please log in.");
 }
 @GetMapping("/me") public User me(Authentication auth){return current(auth);}
 @PutMapping("/me") public User profile(Authentication auth,@RequestBody Profile f){User u=current(auth);if(f.name()!=null&&!f.name().isBlank())u.name=safe(f.name());if(f.mobile()!=null)u.mobile=safe(f.mobile());if(f.city()!=null)u.city=safe(f.city());if(f.state()!=null)u.state=safe(f.state());if(f.bloodGroup()!=null&&u.role.equals("DONOR"))u.bloodGroup=normGroup(f.bloodGroup());if(f.available()!=null&&u.role.equals("DONOR"))u.available=f.available();if(f.latitude()!=null&&f.longitude()!=null){if(Math.abs(f.latitude())>90||Math.abs(f.longitude())>180)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid coordinates");u.latitude=f.latitude();u.longitude=f.longitude();}return users.save(u);}
 @GetMapping("/public/donors") public List<User> donors(@RequestParam(required=false) String bloodGroup,@RequestParam(required=false) String city){return users.findByRoleAndEnabledTrue("DONOR").stream().filter(u->u.available).filter(u->bloodGroup==null||bloodGroup.isBlank()||bloodGroup.equalsIgnoreCase(u.bloodGroup)).filter(u->city==null||city.isBlank()||(u.city!=null&&u.city.toLowerCase().contains(city.toLowerCase().trim()))).map(u->{User d=new User();d.id=u.id;d.name=u.name;d.role=u.role;d.bloodGroup=u.bloodGroup;d.city=u.city;d.state=u.state;d.available=u.available;d.latitude=u.latitude;d.longitude=u.longitude;return d;}).toList();}
 @PostMapping("/requester/requests") public BloodRequest create(Authentication auth,@Valid @RequestBody NewRequest f){User requester=current(auth);BloodRequest r=new BloodRequest();r.requester=requester;r.bloodGroup=normGroup(f.bloodGroup());r.city=safe(f.city());r.hospital=safe(f.hospital());r.phone=safe(f.phone());r.message=safe(f.message());r.unitsRequired=f.unitsRequired()==null?1:f.unitsRequired();r.urgency="NORMAL".equalsIgnoreCase(f.urgency())?"NORMAL":"EMERGENCY";if(f.donorId()!=null){User donor=users.findById(f.donorId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Donor not found"));if(!donor.enabled||!donor.available||!"DONOR".equals(donor.role)||!r.bloodGroup.equals(donor.bloodGroup))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Donor unavailable or group mismatch");r.donor=donor;}return requests.save(r);}
 @GetMapping("/requester/requests") public List<BloodRequest> mine(Authentication a){return requests.findByRequesterIdOrderByCreatedAtDesc(current(a).id);}
 @GetMapping("/donor/requests") public List<BloodRequest> donorRequests(Authentication a){User u=current(a);List<BloodRequest> all=new ArrayList<>(requests.findByDonorIdOrderByCreatedAtDesc(u.id));for(BloodRequest r:requests.findByDonorIsNullAndBloodGroupAndStatusOrderByCreatedAtDesc(u.bloodGroup,"PENDING")){if(r.city.equalsIgnoreCase(safe(u.city)))all.add(r);}all.sort(Comparator.comparing((BloodRequest r)->r.createdAt).reversed());return all;}
 @PostMapping("/donor/requests/{id}/respond") public BloodRequest respond(Authentication a,@PathVariable Long id,@RequestParam String decision){User u=current(a);BloodRequest r=requests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!"PENDING".equals(r.status)||!"DONOR".equals(u.role))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Request already processed");if(r.donor!=null&&!r.donor.id.equals(u.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(r.donor==null&&(!r.bloodGroup.equals(u.bloodGroup)||!r.city.equalsIgnoreCase(safe(u.city))))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(!Set.of("ACCEPTED","REJECTED").contains(decision.toUpperCase()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);r.donor=u;r.status=decision.toUpperCase();return requests.save(r);}
 @GetMapping("/admin/users") public List<User> adminUsers(){return users.findAll();}
 @GetMapping("/admin/requests") public List<BloodRequest> adminRequests(){return requests.findAllByOrderByCreatedAtDesc();}
 @GetMapping("/admin/stats") public Map<String,Long> stats(){List<User> all=users.findAll();List<BloodRequest> r=requests.findAll();return Map.of("users",(long)all.size(),"donors",all.stream().filter(u->u.role.equals("DONOR")).count(),"activeDonors",all.stream().filter(u->u.role.equals("DONOR")&&u.available&&u.enabled).count(),"requests",(long)r.size(),"pending",r.stream().filter(x->x.status.equals("PENDING")).count(),"accepted",r.stream().filter(x->x.status.equals("ACCEPTED")).count());}
 @PutMapping("/admin/users/{id}/toggle") public User toggle(Authentication a,@PathVariable Long id){User u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(u.id.equals(current(a).id)||u.role.equals("ADMIN"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Admin cannot be disabled");u.enabled=!u.enabled;return users.save(u);}
 @PutMapping("/admin/requests/{id}/complete") public BloodRequest complete(@PathVariable Long id){BloodRequest r=requests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!r.status.equals("ACCEPTED"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only accepted requests can be completed");r.status="COMPLETED";return requests.save(r);}
 @ExceptionHandler(org.springframework.web.bind.MethodArgumentNotValidException.class) public ResponseEntity<Map<String,String>> invalid(){return ResponseEntity.badRequest().body(Map.of("message","Please provide valid required details. Password must be at least 8 characters."));}
}
